+// API keys and roles. Keys live in the data as apiKeys: [{ key, name, role }].
+import { AppError } from "../errors.js";
+
+const COOK_WRITES = [
+  ["POST", /^\/recipes\/[^/]+\/cook$/],
+  ["POST", /^\/batches\/[^/]+\/waste$/],
+  ["POST", /^\/temperatures$/],
+  ["POST", /^\/stocktakes\/[^/]+\/counts$/],
+];
+
+/** Finds the caller from the Authorization header; throws `unauthorized` if there is none. */
+export function authenticate(store, headers) {
+  const name = Object.keys(headers).find((h) => h.toLowerCase() === "authorization");
+  const m = /^Bearer\s+(\S+)\s*$/i.exec(name ? String(headers[name]) : "");
+  const found = m && store.data.apiKeys.find((k) => k.key === m[1]);
+  if (!found) throw new AppError("unauthorized");
+  return found;
+}
+
+/** Throws `forbidden` unless the role may make this request. */
+export function authorize(role, method, path) {
+  if (role === "manager") return;
+  if (method === "GET" && path !== "/audit") return;
+  if (role === "cook" && COOK_WRITES.some(([m, re]) => m === method && re.test(path))) return;
+  throw new AppError("forbidden");
+}
